const generateRealisticTrajectory = (range, peakHeight, releaseHeight) => {
  const points = [];
  const numPoints = 30;
  const peakDistance = range * (0.47 + Math.random() * 0.02);
  const a_ascent = (releaseHeight - peakHeight) / (peakDistance ** 2);
  const a_descent = -peakHeight / ((range - peakDistance) ** 2);
  const noiseAmplitude = peakHeight / 70;
  const noiseFrequency = (Math.random() * 3) + 6;
  const noisePhase = Math.random() * Math.PI;

  for (let i = 0; i <= numPoints; i++) {
    const distance = (i / numPoints) * range;
    let baseHeight;
    if (distance <= peakDistance) {
      baseHeight = a_ascent * (distance - peakDistance)**2 + peakHeight;
    } else {
      baseHeight = a_descent * (distance - peakDistance)**2 + peakHeight;
    }
    const sineNoise = noiseAmplitude * Math.sin((distance / range) * noiseFrequency * Math.PI + noisePhase);
    const finalHeight = Math.max(0, baseHeight + sineNoise);
    points.push({ 
      distance: parseFloat(distance.toFixed(2)), 
      height: parseFloat(finalHeight.toFixed(2)) 
    });
  }
  points[0].height = releaseHeight;
  points[points.length - 1].height = 0;
  return points;
};

const mockDataByDate = {
  '2025-09-12': {
    throws: [
      { time: '09:15 AM', playerStats: { range: 84.2, timeOfFlight: 4.1, peakHeight: 15.1, timeToPeak: 2.0, releaseSpeed: 29.5, releaseAngle: 41.5, releaseHeight: 1.8 }, trajectory: generateRealisticTrajectory(84.2, 15.1, 1.8) },
      { time: '09:22 AM', playerStats: { range: 50.5, timeOfFlight: 4.2, peakHeight: 15.3, timeToPeak: 2.1, releaseSpeed: 29.8, releaseAngle: 42.0, releaseHeight: 1.8 }, trajectory: generateRealisticTrajectory(85.5, 15.3, 1.8) },
      { time: '09:30 AM', playerStats: { range: 85.1, timeOfFlight: 4.15, peakHeight: 15.2, timeToPeak: 2.05, releaseSpeed: 29.7, releaseAngle: 41.8, releaseHeight: 1.8 }, trajectory: generateRealisticTrajectory(85.1, 15.2, 1.8) },
      { time: '09:38 AM', playerStats: { range: 83.9, timeOfFlight: 4.0, peakHeight: 14.9, timeToPeak: 2.0, releaseSpeed: 29.4, releaseAngle: 41.0, releaseHeight: 1.8 }, trajectory: generateRealisticTrajectory(83.9, 14.9, 1.8) },
    ]
  },
  '2025-09-05': {
    throws: [
      { time: '10:05 AM', playerStats: { range: 82.1, timeOfFlight: 4.0, peakHeight: 14.1, timeToPeak: 2.0, releaseSpeed: 29.1, releaseAngle: 41.0, releaseHeight: 1.85 }, trajectory: generateRealisticTrajectory(82.1, 14.1, 1.85) },
      { time: '10:12 AM', playerStats: { range: 81.8, timeOfFlight: 3.9, peakHeight: 14.0, timeToPeak: 1.95, releaseSpeed: 29.0, releaseAngle: 40.8, releaseHeight: 1.85 }, trajectory: generateRealisticTrajectory(81.8, 14.0, 1.85) },
    ]
  },
};

export const fetchAvailableDates = async () => {
  return new Promise((resolve) => {
    setTimeout(() => {
      const datesWithCount = Object.keys(mockDataByDate).map(date => ({ 
        value: date, 
        label: date, 
        throwCount: mockDataByDate[date].throws.length 
      }));
      resolve(datesWithCount);
    }, 200);
  });
};

export const fetchJavelinDataByDate = async (date) => {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (mockDataByDate[date]) {
        resolve(mockDataByDate[date]);
      } else {
        reject('No data found for this date');
      }
    }, 300);
  });
};
